-- ============================================================
--  081_quices_actividades_foros_calidad.sql — quizzes, actividades y foros, lote «calidad»
--
--  Generado por scripts/evaluacion-aula.mjs calidad migracion --publica
--  a partir de contenido/aula/catalogo. No editar a mano.
--
--  Cursos: Gestión de Calidad Farmacéutica; Aseguramiento de la Calidad; Control de Calidad de Medicamentos; Buenas Prácticas de Manufactura; Buenas Prácticas de Laboratorio; Buenas Prácticas de Documentación; Auditoría de Calidad Farmacéutica; Gestión de Riesgos en la Calidad; Desviaciones y CAPA; Validación de Métodos Analíticos.
--
--  Qué hace en cada curso (aprobado por la dirección académica: todos
--  los cursos llevan quizzes, actividades y foros):
--   1. Nota mínima 70, 2 intentos y política 60/30/10.
--   2. Crea PUBLICADOS un quiz por unidad, las actividades con rúbrica y
--      los foros; si ya existían en borrador, los publica. No toca
--      preguntas de quizzes con intentos ni rúbricas o pesos de recursos
--      con entregas o notas.
--   3. Sin guías docentes: esas quedan en la versión privada.
--   4. Si el curso o alguna unidad no está en la base, lo salta con un
--      aviso: nunca detiene el arranque del servidor.
-- ============================================================

-- ════════════════════════════════════════════════════════════════
--  Curso de Gestión de Calidad Farmacéutica
--  5 quizzes · 5 actividades · 6 foros
-- ════════════════════════════════════════════════════════════════
DO $evgcal$
DECLARE
  v_curso    BIGINT;
  v_unidad   BIGINT;
  v_banco    BIGINT;
  v_pregunta BIGINT;
  v_eval     BIGINT;
  v_act      BIGINT;
  v_foro     BIGINT;
  v_t1 TEXT; v_t2 TEXT; v_t3 TEXT; v_t4 TEXT; v_t5 TEXT; v_t6 TEXT; v_t7 TEXT;
  v_j1 JSONB; v_j2 JSONB;
  v_a1 TEXT[];
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = 'Curso de Gestión de Calidad Farmacéutica' AND deleted_at IS NULL
   LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'No existe el curso Curso de Gestión de Calidad Farmacéutica: se salta.';
    RETURN;
  END IF;

  -- Si alguien cambió las unidades en el panel, no se fuerza nada.
  IF (SELECT COUNT(DISTINCT title) FROM aula_modules
       WHERE course_id = v_curso AND deleted_at IS NULL
         AND title = ANY(ARRAY['Unidad 1. Fundamentos de la gestión de calidad farmacéutica', 'Unidad 2. Marco normativo colombiano de la calidad farmacéutica', 'Unidad 3. Modelos de sistema de gestión de calidad: ICH Q10 e ISO 9001:2015', 'Unidad 4. Enfoque por procesos, indicadores y revisión por la dirección', 'Unidad 5. Mejora continua, gestión del cambio y cultura de calidad']::text[])) < 5 THEN
    RAISE NOTICE 'Gestión de Calidad Farmacéutica: sus unidades no coinciden con el paquete; se salta.';
    RETURN;
  END IF;

  UPDATE aula_courses
     SET passing_score = 70, max_attempts = 2, grade_policy = $evgcal_json${"version":1,"components":{"activities":60,"quizzes":30,"forums":10},"rounding":"half_up"}$evgcal_json$::jsonb, updated_at = NOW()
   WHERE id = v_curso;


  -- ── Quiz gcal-u1-quiz ──────────────────────────────────────
  SELECT id INTO v_unidad FROM aula_modules
   WHERE course_id = v_curso AND title = 'Unidad 1. Fundamentos de la gestión de calidad farmacéutica' AND deleted_at IS NULL
   LIMIT 1;
  IF v_unidad IS NULL THEN
    RAISE EXCEPTION 'No existe la unidad 1 (Unidad 1. Fundamentos de la gestión de calidad farmacéutica) en Gestión de Calidad Farmacéutica.';
  END IF;
  v_t1 := 'Evaluación de la Unidad 1 · Fundamentos de la gestión de calidad farmacéutica';
  v_t2 := 'Cuatro preguntas de selección múltiple con una sola respuesta correcta, ordenadas según la taxonomía de Bloom: comprender, aplicar, analizar y evaluar. Cada una vale 25 puntos. Tienes dos intentos y se conserva la nota mayor. La retroalimentación de cada opción se muestra después de enviar.';
  SELECT id INTO v_banco FROM aula_question_banks
   WHERE course_id = v_curso AND name = v_t1 AND deleted_at IS NULL LIMIT 1;
  IF v_banco IS NULL THEN
    INSERT INTO aula_question_banks (course_id, name, description)
    VALUES (v_curso, v_t1, v_t2)
    RETURNING id INTO v_banco;
  END IF;

  SELECT id INTO v_eval FROM aula_assessments
   WHERE course_id = v_curso AND title = v_t1 AND deleted_at IS NULL LIMIT 1;
  IF v_eval IS NULL THEN
    INSERT INTO aula_assessments
      (course_id, module_id, title, instructions_html, is_required, passing_score, max_attempts,
       shuffle_questions, shuffle_options, show_answers_after_submit, status, sort_order, weight)
    VALUES
      (v_curso, v_unidad, v_t1, v_t2, TRUE, 70, 2,
       FALSE, FALSE, TRUE, 'publicado', 1, 6)
    RETURNING id INTO v_eval;
  END IF;
  UPDATE aula_assessments SET status = 'publicado', updated_at = NOW() WHERE id = v_eval AND status = 'borrador';

  IF EXISTS (SELECT 1 FROM aula_attempts WHERE assessment_id = v_eval) THEN
    RAISE NOTICE 'El quiz % ya tiene intentos: no se modifican sus preguntas ni su configuración.', v_t1;
  ELSE
    UPDATE aula_assessments
       SET module_id = v_unidad, instructions_html = v_t2, is_required = TRUE,
           passing_score = 70, max_attempts = 2, shuffle_options = FALSE,
           show_answers_after_submit = TRUE, sort_order = 1, weight = 6, updated_at = NOW()
     WHERE id = v_eval;
    DELETE FROM aula_assessment_questions WHERE assessment_id = v_eval;


    v_t3 := '¿Qué distingue el aseguramiento de la calidad de la etapa de inspección en la evolución histórica de la calidad?';
    v_t4 := 'La calidad pasó de la inspección del producto terminado al control estadístico, luego al aseguramiento (prevenir con sistemas y procesos), a la calidad total y a los sistemas de gestión. La regulación farmacéutica refleja ese paso: las BPM buscan construir la calidad en el proceso.';
    v_j1 := $evgcal_json${"external_id":"gcal-u1-q1","cognitive_level":"Comprender","difficulty":"baja","lesson_title":"Evolución histórica de la calidad: de la inspección a la gestión total","outcome":"Evolución histórica de la calidad: de la inspección a la gestión total","source":"ISO 9000:2015, fundamentos; OMS TRS 986, anexo 2."}$evgcal_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'gcal-u1-q1' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
    ELSE
      UPDATE aula_questions
         SET prompt_html = v_t3, points = 25, general_feedback = v_t4, explanation = v_t4, config = v_j1, updated_at = NOW()
       WHERE id = v_pregunta;
    END IF;
    DELETE FROM aula_question_options WHERE question_id = v_pregunta;
    INSERT INTO aula_question_options (question_id, text, is_correct, feedback, sort_order) VALUES
      (v_pregunta, 'La inspección es más moderna porque usa equipos automáticos de medición en la línea de producción.', FALSE, 'La inspección es la etapa más antigua; la automatización no cambia su lógica de detectar al final.', 0),
      (v_pregunta, 'El aseguramiento previene defectos con procesos planificados; la inspección los detecta al final.', TRUE, 'Correcto. El paso de detectar a prevenir es el cambio de fondo entre ambas etapas.', 1),
      (v_pregunta, 'El aseguramiento consiste en inspeccionar el ciento por ciento de las unidades antes de liberarlas.', FALSE, 'Inspeccionar todo sigue siendo inspección; el aseguramiento actúa sobre el proceso, no solo sobre el producto.', 2),
      (v_pregunta, 'No hay diferencia de fondo: ambos se basan en revisar el producto terminado al final del proceso.', FALSE, 'Sí la hay: el aseguramiento construye la calidad en el proceso, antes de que el producto exista.', 3);
    INSERT INTO aula_assessment_questions (assessment_id, question_id, sort_order, points_override)
    VALUES (v_eval, v_pregunta, 0, 25);


    v_t3 := 'En un servicio farmacéutico suben los errores de dispensación. El equipo analiza causas, prueba un doble chequeo en un turno, mide los errores durante un mes y, como bajan, lo adopta en todos los turnos. ¿A qué fase del PHVA corresponde medir los errores durante el mes?';
    v_t4 := 'En el ciclo de Deming se planea (causas y cambio), se hace (prueba a pequeña escala), se verifica (se miden y comparan los resultados) y se actúa (se estandariza o se ajusta).';
    v_j1 := $evgcal_json${"external_id":"gcal-u1-q2","cognitive_level":"Aplicar","difficulty":"media","lesson_title":"Aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica","outcome":"Aportes de Deming, Juran y Crosby a la gestión de calidad farmacéutica","source":"Ciclo PHVA (Deming); ISO 9001:2015, introducción (0.3.2)."}$evgcal_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'gcal-u1-q2' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
    ELSE
      UPDATE aula_questions
         SET prompt_html = v_t3, points = 25, general_feedback = v_t4, explanation = v_t4, config = v_j1, updated_at = NOW()
       WHERE id = v_pregunta;
    END IF;
    DELETE FROM aula_question_options WHERE question_id = v_pregunta;
    INSERT INTO aula_question_options (question_id, text, is_correct, feedback, sort_order) VALUES
      (v_pregunta, 'A Planear, porque medir sirve para fijar la meta del proyecto de mejora antes de actuar.', FALSE, 'La meta se fija antes de probar el cambio; aquí la medición evalúa lo que ya se probó.', 0),
      (v_pregunta, 'A Hacer, porque la medición ocurre al mismo tiempo que se prueba el doble chequeo en el turno.', FALSE, 'Hacer es ejecutar el cambio a pequeña escala; comparar sus resultados con lo esperado es otra fase.', 1),
      (v_pregunta, 'A Actuar, porque los datos del mes llevan a la decisión de extender el cambio a todos los turnos.', FALSE, 'Actuar es estandarizar o ajustar a partir de lo verificado; la medición la precede.', 2),
      (v_pregunta, 'A Verificar, porque compara los resultados de la prueba con lo que se esperaba lograr.', TRUE, 'Correcto. Verificar es medir y comparar antes de decidir si se estandariza.', 3);
    INSERT INTO aula_assessment_questions (assessment_id, question_id, sort_order, points_override)
    VALUES (v_eval, v_pregunta, 1, 25);


    v_t3 := 'Una línea de envasado cumplió la meta de 10.000 unidades por turno, pero usó un 30 % más de horas extra y de material que lo planificado. ¿Qué análisis es correcto según el vocabulario de ISO 9000?';
    v_t4 := 'ISO 9000 define la eficacia como el grado en que se realizan las actividades planificadas y se logran los resultados planificados, y la eficiencia como la relación entre el resultado alcanzado y los recursos utilizados.';
    v_j1 := $evgcal_json${"external_id":"gcal-u1-q3","cognitive_level":"Analizar","difficulty":"media","lesson_title":"Vocabulario esencial del SGC: requisito, conformidad, proceso, eficacia, eficiencia","outcome":"Vocabulario esencial del SGC: requisito, conformidad, proceso, eficacia, eficiencia","source":"ISO 9000:2015, términos 3.7.11 (eficacia) y 3.7.10 (eficiencia)."}$evgcal_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'gcal-u1-q3' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
    ELSE
      UPDATE aula_questions
         SET prompt_html = v_t3, points = 25, general_feedback = v_t4, explanation = v_t4, config = v_j1, updated_at = NOW()
       WHERE id = v_pregunta;
    END IF;
    DELETE FROM aula_question_options WHERE question_id = v_pregunta;
    INSERT INTO aula_question_options (question_id, text, is_correct, feedback, sort_order) VALUES
      (v_pregunta, 'Fue eficaz, porque logró el resultado planificado, pero no eficiente, porque usó más recursos.', TRUE, 'Correcto. Eficacia mira el resultado; eficiencia, la relación entre resultado y recursos.', 0),
      (v_pregunta, 'Fue eficiente porque cumplió la meta, y la eficacia es un concepto que no aplica a la producción.', FALSE, 'Cumplir la meta es eficacia. La eficiencia considera los recursos, que aquí se excedieron.', 1),
      (v_pregunta, 'No fue eficaz ni eficiente: cualquier sobrecosto anula el cumplimiento de la meta de producción.', FALSE, 'El sobrecosto afecta la eficiencia, no borra que el resultado planificado se logró.', 2),
      (v_pregunta, 'Fue eficiente pero no eficaz: produjo lo previsto, aunque con un costo menor del planificado.', FALSE, 'El costo fue mayor, no menor, y el resultado sí se logró: la relación está invertida.', 3);
    INSERT INTO aula_assessment_questions (assessment_id, question_id, sort_order, points_override)
    VALUES (v_eval, v_pregunta, 2, 25);


    v_t3 := 'La gerencia de un laboratorio propone reducir los análisis de materias primas porque «el cliente no los ve y encarecen el producto». ¿Cuál es la valoración más sólida?';
    v_t4 := 'La calidad del medicamento es condición de su seguridad y eficacia, y el paciente no puede verificarla. Por eso las BPM exigen un sistema de calidad farmacéutico con controles que no dependen de la percepción del cliente.';
    v_j1 := $evgcal_json${"external_id":"gcal-u1-q4","cognitive_level":"Evaluar","difficulty":"alta","lesson_title":"Calidad del medicamento: por qué la industria farmacéutica requiere un sistema propio","outcome":"Calidad del medicamento: por qué la industria farmacéutica requiere un sistema propio","source":"OMS TRS 986, anexo 2, principios; ISO 9000:2015, principio de enfoque al cliente."}$evgcal_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'gcal-u1-q4' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
    ELSE
      UPDATE aula_questions
         SET prompt_html = v_t3, points = 25, general_feedback = v_t4, explanation = v_t4, config = v_j1, updated_at = NOW()
       WHERE id = v_pregunta;
    END IF;
    DELETE FROM aula_question_options WHERE question_id = v_pregunta;
    INSERT INTO aula_question_options (question_id, text, is_correct, feedback, sort_order) VALUES
      (v_pregunta, 'Es aceptable si se apoya en el enfoque al cliente, que prioriza lo que el cliente percibe y valora.', FALSE, 'En el medicamento, el paciente no puede percibir la calidad: por eso existe un sistema que la garantice.', 0),
      (v_pregunta, 'Es aceptable si se documenta como una decisión basada en evidencia de costos de la empresa.', FALSE, 'La evidencia de costos no reemplaza la evidencia de calidad que exigen las BPM.', 1),
      (v_pregunta, 'Es inaceptable: esos controles protegen la seguridad y la eficacia, y las BPM los exigen.', TRUE, 'Correcto. La calidad farmacéutica no se negocia con la percepción del cliente.', 2),
      (v_pregunta, 'Es inaceptable solo porque podría disminuir la satisfacción de los distribuidores con el producto.', FALSE, 'El problema no es comercial: es el riesgo para el paciente y el incumplimiento de las BPM.', 3);
    INSERT INTO aula_assessment_questions (assessment_id, question_id, sort_order, points_override)
    VALUES (v_eval, v_pregunta, 3, 25);

  END IF;


  -- ── Quiz gcal-u2-quiz ──────────────────────────────────────
  SELECT id INTO v_unidad FROM aula_modules
   WHERE course_id = v_curso AND title = 'Unidad 2. Marco normativo colombiano de la calidad farmacéutica' AND deleted_at IS NULL
   LIMIT 1;
  IF v_unidad IS NULL THEN
    RAISE EXCEPTION 'No existe la unidad 2 (Unidad 2. Marco normativo colombiano de la calidad farmacéutica) en Gestión de Calidad Farmacéutica.';
  END IF;
  v_t1 := 'Evaluación de la Unidad 2 · Marco normativo colombiano de la calidad farmacéutica';
  v_t2 := 'Cuatro preguntas de selección múltiple con una sola respuesta correcta, ordenadas según la taxonomía de Bloom: comprender, aplicar, analizar y evaluar. Cada una vale 25 puntos. Tienes dos intentos y se conserva la nota mayor. La retroalimentación de cada opción se muestra después de enviar.';
  SELECT id INTO v_banco FROM aula_question_banks
   WHERE course_id = v_curso AND name = v_t1 AND deleted_at IS NULL LIMIT 1;
  IF v_banco IS NULL THEN
    INSERT INTO aula_question_banks (course_id, name, description)
    VALUES (v_curso, v_t1, v_t2)
    RETURNING id INTO v_banco;
  END IF;

  SELECT id INTO v_eval FROM aula_assessments
   WHERE course_id = v_curso AND title = v_t1 AND deleted_at IS NULL LIMIT 1;
  IF v_eval IS NULL THEN
    INSERT INTO aula_assessments
      (course_id, module_id, title, instructions_html, is_required, passing_score, max_attempts,
       shuffle_questions, shuffle_options, show_answers_after_submit, status, sort_order, weight)
    VALUES
      (v_curso, v_unidad, v_t1, v_t2, TRUE, 70, 2,
       FALSE, FALSE, TRUE, 'publicado', 2, 6)
    RETURNING id INTO v_eval;
  END IF;
  UPDATE aula_assessments SET status = 'publicado', updated_at = NOW() WHERE id = v_eval AND status = 'borrador';

  IF EXISTS (SELECT 1 FROM aula_attempts WHERE assessment_id = v_eval) THEN
    RAISE NOTICE 'El quiz % ya tiene intentos: no se modifican sus preguntas ni su configuración.', v_t1;
  ELSE
    UPDATE aula_assessments
       SET module_id = v_unidad, instructions_html = v_t2, is_required = TRUE,
           passing_score = 70, max_attempts = 2, shuffle_options = FALSE,
           show_answers_after_submit = TRUE, sort_order = 2, weight = 6, updated_at = NOW()
     WHERE id = v_eval;
    DELETE FROM aula_assessment_questions WHERE assessment_id = v_eval;


    v_t3 := '¿Qué papel cumple la Resolución 1160 de 2016 en el mapa normativo de la calidad farmacéutica en Colombia?';
    v_t4 := 'La Resolución 1160 de 2016 establece los manuales de buenas prácticas de manufactura y las guías de inspección para obtener el certificado de BPM, con base en los informes técnicos de la OMS; la modificó la Resolución 2190 de 2020.';
    v_j1 := $evgcal_json${"external_id":"gcal-u2-q1","cognitive_level":"Comprender","difficulty":"baja","lesson_title":"Resolución 1160 de 2016 y la adopción del Informe 37 OMS: alcance para el SGC","outcome":"Resolución 1160 de 2016 y la adopción del Informe 37 OMS: alcance para el SGC","source":"Resolución 1160 de 2016 (modificada por la Resolución 2190 de 2020)."}$evgcal_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'gcal-u2-q1' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
    ELSE
      UPDATE aula_questions
         SET prompt_html = v_t3, points = 25, general_feedback = v_t4, explanation = v_t4, config = v_j1, updated_at = NOW()
       WHERE id = v_pregunta;
    END IF;
    DELETE FROM aula_question_options WHERE question_id = v_pregunta;
    INSERT INTO aula_question_options (question_id, text, is_correct, feedback, sort_order) VALUES
      (v_pregunta, 'Regula el servicio farmacéutico de las IPS y de los establecimientos farmacéuticos minoristas del país.', FALSE, 'Esa es la materia del Decreto 2200 de 2005 y de la Resolución 1403 de 2007.', 0),
      (v_pregunta, 'Define el régimen de registros sanitarios de medicamentos y las modalidades de cada registro.', FALSE, 'Esa es la materia del Decreto 677 de 1995.', 1),
      (v_pregunta, 'Establece los manuales de BPM y las guías de inspección con las que se certifica a los fabricantes.', TRUE, 'Correcto. Adopta las BPM de la OMS (informes 37 y 45) para la certificación de fabricantes.', 2),
      (v_pregunta, 'Crea el Invima como autoridad sanitaria nacional y define su naturaleza y sus funciones.', FALSE, 'El Invima lo creó la Ley 100 de 1993.', 3);
    INSERT INTO aula_assessment_questions (assessment_id, question_id, sort_order, points_override)
    VALUES (v_eval, v_pregunta, 0, 25);


    v_t3 := 'Un laboratorio titular quiere trasladar la fabricación de un medicamento registrado a otro fabricante por contrato. ¿Qué secuencia es correcta?';
    v_t4 := 'Un cambio que altera las condiciones aprobadas del registro se evalúa en el control de cambios del sistema de calidad y se tramita ante el Invima según su clasificación de riesgo (Decreto 334 de 2022). No hay «renovación» en la cual notificarlo: desde el Decreto 1474 de 2023 la vigencia del registro de medicamentos es indefinida.';
    v_j1 := $evgcal_json${"external_id":"gcal-u2-q2","cognitive_level":"Aplicar","difficulty":"media","lesson_title":"Cambios con impacto en la calidad y su trámite ante el INVIMA","outcome":"Cambios con impacto en la calidad y su trámite ante el INVIMA","source":"Decreto 334 de 2022, artículos 5 y 8; Decreto 1474 de 2023; ICH Q10, gestión del cambio."}$evgcal_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'gcal-u2-q2' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
    ELSE
      UPDATE aula_questions
         SET prompt_html = v_t3, points = 25, general_feedback = v_t4, explanation = v_t4, config = v_j1, updated_at = NOW()
       WHERE id = v_pregunta;
    END IF;
    DELETE FROM aula_question_options WHERE question_id = v_pregunta;
    INSERT INTO aula_question_options (question_id, text, is_correct, feedback, sort_order) VALUES
      (v_pregunta, 'Evaluarlo en control de cambios, preparar el soporte y tramitar la modificación que corresponda antes de implementarlo.', TRUE, 'Correcto. El control interno y el trámite regulatorio van juntos, y el cambio se implementa cuando la norma lo permite.', 0),
      (v_pregunta, 'Implementar el cambio y notificarlo al Invima en la siguiente renovación del registro sanitario del producto afectado.', FALSE, 'Desde el Decreto 1474 de 2023 no hay renovación periódica: los cambios se tramitan como modificación.', 1),
      (v_pregunta, 'Tramitar solo el control de cambios interno, porque el fabricante por contrato no figura en el registro.', FALSE, 'El fabricante sí es parte de las condiciones aprobadas del registro.', 2),
      (v_pregunta, 'Pedir autorización verbal al inspector del Invima en la próxima visita y documentarla después.', FALSE, 'Las modificaciones se tramitan formalmente; una conversación en una visita no las reemplaza.', 3);
    INSERT INTO aula_assessment_questions (assessment_id, question_id, sort_order, points_override)
    VALUES (v_eval, v_pregunta, 1, 25);


