    v_j1 := $evacal_json${"external_id":"acal-u2-q2","cognitive_level":"Aplicar","difficulty":"media","lesson_title":"Procedimiento de revisión del registro de lote por QA","outcome":"Procedimiento de revisión del registro de lote por QA","source":"OMS TRS 986, anexo 2, operaciones de empaque y conciliación."}$evacal_json$::jsonb;
