      (v_pregunta, 'No se reincorporan: sin evidencia de cómo se almacenaron, su calidad no está garantizada.', TRUE, 'Correcto. Se destruyen o, si procede, se investigan antes de cualquier otra decisión.', 1),
      (v_pregunta, 'Se reacondicionan con etiquetas nuevas y se venden a otro cliente con un descuento comercial.', FALSE, 'Reetiquetar no corrige la falta de evidencia sobre el almacenamiento.', 2),
