    DELETE FROM aula_question_options WHERE question_id = v_pregunta;
    INSERT INTO aula_question_options (question_id, text, is_correct, feedback, sort_order) VALUES
      (v_pregunta, 'Es aceptable si el resultado microbiológico llega conforme una semana después del despacho.', FALSE, 'Un resultado conforme posterior no corrige una liberación hecha sin él.', 0),
      (v_pregunta, 'Es inaceptable: no se libera ni se despacha un lote con ensayos de la especificación pendientes.', TRUE, 'Correcto. El certificado debe reflejar todos los ensayos terminados y conformes.', 1),
      (v_pregunta, 'Es aceptable para productos de alta rotación que no pueden esperar mucho tiempo en la bodega.', FALSE, 'La rotación comercial no es un criterio de liberación.', 2),
