-- ════════════════════════════════════════════════════════════════
--  Curso de Buenas Prácticas de Manufactura — BPM
--  5 quizzes · 5 actividades · 6 foros
-- ════════════════════════════════════════════════════════════════
DO $evbpmc$
DECLARE
  v_curso    BIGINT;
  v_unidad   BIGINT;
  v_banco    BIGINT;
  v_pregunta BIGINT;
  v_eval     BIGINT;
  v_act      BIGINT;
  v_foro     BIGINT;
  v_t1 TEXT; v_t2 TEXT; v_t3 TEXT; v_t4 TEXT; v_t5 TEXT; v_t6 TEXT; v_t7 TEXT;
  v_j1 JSONB; v_j2 JSONB;
  v_a1 TEXT[];
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = 'Curso de Buenas Prácticas de Manufactura — BPM' AND deleted_at IS NULL
   LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'No existe el curso Curso de Buenas Prácticas de Manufactura — BPM: se salta.';
    RETURN;
  END IF;

  -- Si alguien cambió las unidades en el panel, no se fuerza nada.
  IF (SELECT COUNT(DISTINCT title) FROM aula_modules
       WHERE course_id = v_curso AND deleted_at IS NULL
         AND title = ANY(ARRAY['Unidad 1. Fundamentos y marco regulatorio de las BPM en Colombia', 'Unidad 2. Personal, instalaciones, equipos y sistemas de apoyo crítico', 'Unidad 3. Producción, contaminación cruzada y materiales', 'Unidad 4. Productos estériles (Anexo 1)', 'Unidad 5. Contratos, autoinspección y certificación INVIMA']::text[])) < 5 THEN
    RAISE NOTICE 'Buenas Prácticas de Manufactura: sus unidades no coinciden con el paquete; se salta.';
    RETURN;
  END IF;

  UPDATE aula_courses
     SET passing_score = 70, max_attempts = 2, grade_policy = $evbpmc_json${"version":1,"components":{"activities":60,"quizzes":30,"forums":10},"rounding":"half_up"}$evbpmc_json$::jsonb, updated_at = NOW()
   WHERE id = v_curso;


  -- ── Quiz bpmc-u1-quiz ──────────────────────────────────────
  SELECT id INTO v_unidad FROM aula_modules
   WHERE course_id = v_curso AND title = 'Unidad 1. Fundamentos y marco regulatorio de las BPM en Colombia' AND deleted_at IS NULL
   LIMIT 1;
  IF v_unidad IS NULL THEN
    RAISE EXCEPTION 'No existe la unidad 1 (Unidad 1. Fundamentos y marco regulatorio de las BPM en Colombia) en Buenas Prácticas de Manufactura.';
  END IF;
  v_t1 := 'Evaluación de la Unidad 1 · Fundamentos y marco regulatorio de las BPM en Colombia';
  v_t2 := 'Cuatro preguntas de selección múltiple con una sola respuesta correcta, ordenadas según la taxonomía de Bloom: comprender, aplicar, analizar y evaluar. Cada una vale 25 puntos. Tienes dos intentos y se conserva la nota mayor. La retroalimentación de cada opción se muestra después de enviar.';
  SELECT id INTO v_banco FROM aula_question_banks
   WHERE course_id = v_curso AND name = v_t1 AND deleted_at IS NULL LIMIT 1;
  IF v_banco IS NULL THEN
    INSERT INTO aula_question_banks (course_id, name, description)
    VALUES (v_curso, v_t1, v_t2)
    RETURNING id INTO v_banco;
  END IF;

  SELECT id INTO v_eval FROM aula_assessments
   WHERE course_id = v_curso AND title = v_t1 AND deleted_at IS NULL LIMIT 1;
  IF v_eval IS NULL THEN
    INSERT INTO aula_assessments
      (course_id, module_id, title, instructions_html, is_required, passing_score, max_attempts,
       shuffle_questions, shuffle_options, show_answers_after_submit, status, sort_order, weight)
    VALUES
      (v_curso, v_unidad, v_t1, v_t2, TRUE, 70, 2,
       FALSE, FALSE, TRUE, 'publicado', 1, 6)
    RETURNING id INTO v_eval;
  END IF;
  UPDATE aula_assessments SET status = 'publicado', updated_at = NOW() WHERE id = v_eval AND status = 'borrador';

  IF EXISTS (SELECT 1 FROM aula_attempts WHERE assessment_id = v_eval) THEN
    RAISE NOTICE 'El quiz % ya tiene intentos: no se modifican sus preguntas ni su configuración.', v_t1;
  ELSE
    UPDATE aula_assessments
       SET module_id = v_unidad, instructions_html = v_t2, is_required = TRUE,
           passing_score = 70, max_attempts = 2, shuffle_options = FALSE,
           show_answers_after_submit = TRUE, sort_order = 1, weight = 6, updated_at = NOW()
     WHERE id = v_eval;
    DELETE FROM aula_assessment_questions WHERE assessment_id = v_eval;


    v_t3 := '¿Qué relación hay entre la tragedia de la talidomida y el origen de las BPM?';
    v_t4 := 'La tragedia de la talidomida (malformaciones en miles de recién nacidos a comienzos de los años sesenta) impulsó en Estados Unidos las enmiendas Kefauver-Harris de 1962 y, en el plano internacional, el primer texto de BPM de la OMS a finales de esa década.';
    v_j1 := $evbpmc_json${"external_id":"bpmc-u1-q1","cognitive_level":"Comprender","difficulty":"baja","lesson_title":"Origen de las BPM: de la tragedia de la talidomida a la OMS","outcome":"Origen de las BPM: de la tragedia de la talidomida a la OMS","source":"Historia de la regulación farmacéutica; OMS, textos de BPM (1968-1969)."}$evbpmc_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'bpmc-u1-q1' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
    ELSE
      UPDATE aula_questions
         SET prompt_html = v_t3, points = 25, general_feedback = v_t4, explanation = v_t4, config = v_j1, updated_at = NOW()
       WHERE id = v_pregunta;
    END IF;
    DELETE FROM aula_question_options WHERE question_id = v_pregunta;
    INSERT INTO aula_question_options (question_id, text, is_correct, feedback, sort_order) VALUES
      (v_pregunta, 'Fue causada por un error de etiquetado en una planta, lo que llevó a crear el despeje de línea.', FALSE, 'El daño de la talidomida fue su efecto teratogénico, no un error de etiquetado.', 0),
      (v_pregunta, 'Mostró la necesidad de evidencia y controles sistemáticos, e impulsó las enmiendas de 1962 y las BPM.', TRUE, 'Correcto. Las enmiendas Kefauver-Harris y el primer texto de BPM de la OMS vinieron después.', 1),
      (v_pregunta, 'Ocurrió por la contaminación microbiana de un inyectable, origen de las normas para estériles.', FALSE, 'La talidomida se administraba por vía oral; no fue un problema de contaminación.', 2),
      (v_pregunta, 'Obligó a la OMS a prohibir los medicamentos sedantes en todos sus Estados miembros desde 1962.', FALSE, 'La OMS no prohibió los sedantes; el cambio fue en la regulación y en los controles.', 3);
    INSERT INTO aula_assessment_questions (assessment_id, question_id, sort_order, points_override)
    VALUES (v_eval, v_pregunta, 0, 25);


    v_t3 := 'El procedimiento interno de un fabricante colombiano dice que la certificación de BPM se tramita «según el Decreto 549 de 2001». ¿Qué le respondes?';
    v_t4 := 'La certificación de buenas prácticas se tramita hoy con el Decreto 335 de 2022, que derogó el Decreto 549 de 2001. Los manuales técnicos de BPM son los de la Resolución 1160 de 2016.';
    v_j1 := $evbpmc_json${"external_id":"bpmc-u1-q2","cognitive_level":"Aplicar","difficulty":"media","lesson_title":"Decreto 677 de 1995 y Decreto 549 de 2001: base legal de la fabricación y la certificación","outcome":"Decreto 677 de 1995 y Decreto 549 de 2001: base legal de la fabricación y la certificación","source":"Decreto 335 de 2022; Resolución 1160 de 2016."}$evbpmc_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'bpmc-u1-q2' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
    ELSE
      UPDATE aula_questions
         SET prompt_html = v_t3, points = 25, general_feedback = v_t4, explanation = v_t4, config = v_j1, updated_at = NOW()
       WHERE id = v_pregunta;
    END IF;
    DELETE FROM aula_question_options WHERE question_id = v_pregunta;
    INSERT INTO aula_question_options (question_id, text, is_correct, feedback, sort_order) VALUES
      (v_pregunta, 'El Decreto 549 de 2001 sigue vigente y es la única norma que regula la certificación de BPM.', FALSE, 'Ya no está vigente: fue derogado.', 0),
      (v_pregunta, 'La certificación ya no existe: con el registro sanitario basta para fabricar medicamentos.', FALSE, 'La certificación de BPM sigue siendo obligatoria para fabricar.', 1),
      (v_pregunta, 'La certificación se tramita hoy con la norma ISO 9001 ante un organismo de certificación acreditado.', FALSE, 'ISO 9001 es voluntaria y no sustituye la certificación sanitaria.', 2),
      (v_pregunta, 'Debe actualizarse: el Decreto 549 fue derogado y hoy rige el Decreto 335 de 2022.', TRUE, 'Correcto. El procedimiento debe citar la norma vigente.', 3);
    INSERT INTO aula_assessment_questions (assessment_id, question_id, sort_order, points_override)
    VALUES (v_eval, v_pregunta, 1, 25);


    v_t3 := 'Una planta quiere fabricar en la misma área una penicilina y un antihipertensivo, alternando campañas con limpieza validada. ¿Qué análisis es correcto?';
    v_t4 := 'Las penicilinas y otros betalactámicos pueden causar reacciones graves en personas sensibilizadas incluso en trazas; por eso las BPM y la Resolución 3028 de 2008 exigen áreas dedicadas y separadas para ellos.';
    v_j1 := $evbpmc_json${"external_id":"bpmc-u1-q3","cognitive_level":"Analizar","difficulty":"media","lesson_title":"Normas especiales: Res. 3028/2008 (áreas especiales), fitoterapéuticos (Res. 3131/1998, Decreto 2266/2004)","outcome":"Normas especiales: Res. 3028/2008 (áreas especiales), fitoterapéuticos (Res. 3131/1998, Decreto 2266/2004)","source":"Resolución 3028 de 2008; OMS TRS 986, anexo 2 (prevención de la contaminación cruzada)."}$evbpmc_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'bpmc-u1-q3' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
