  v_j2 := $evbpmc_json${"version":1,"total":100,"criteria":[{"id":"estado-de-las-normas","name":"Estado de las normas","weight":30,"levels":[{"level":4,"label":"Destacado","description":"Determina con acierto el estado de las seis referencias, con fuente y fecha de consulta."},{"level":3,"label":"Logrado","description":"Acierta en cinco referencias."},{"level":2,"label":"En desarrollo","description":"Cumple el criterio de forma parcial o general, con errores u omisiones que no invalidan el resultado."},{"level":1,"label":"Inicial","description":"Lo intenta, pero con errores importantes o sin relación con el caso."},{"level":0,"label":"Sin evidencia","description":"No hay evidencia de este criterio en la entrega."}]},{"id":"norma-vigente","name":"Norma vigente","weight":25,"levels":[{"level":4,"label":"Destacado","description":"Identifica la norma que reemplaza cada referencia desactualizada."},{"level":3,"label":"Logrado","description":"Identifica la mayoría con alguna imprecisión."},{"level":2,"label":"En desarrollo","description":"Cumple el criterio de forma parcial o general, con errores u omisiones que no invalidan el resultado."},{"level":1,"label":"Inicial","description":"Lo intenta, pero con errores importantes o sin relación con el caso."},{"level":0,"label":"Sin evidencia","description":"No hay evidencia de este criterio en la entrega."}]},{"id":"impacto-en-la-practica","name":"Impacto en la práctica","weight":25,"levels":[{"level":4,"label":"Destacado","description":"Explica el cambio práctico y los procedimientos que deben revisarse."},{"level":3,"label":"Logrado","description":"Explica los cambios con generalidades."},{"level":2,"label":"En desarrollo","description":"Cumple el criterio de forma parcial o general, con errores u omisiones que no invalidan el resultado."},{"level":1,"label":"Inicial","description":"Lo intenta, pero con errores importantes o sin relación con el caso."},{"level":0,"label":"Sin evidencia","description":"No hay evidencia de este criterio en la entrega."}]},{"id":"control-de-actualizacion","name":"Control de actualización","weight":10,"levels":[{"level":4,"label":"Destacado","description":"Propone un control concreto, con responsable y frecuencia."},{"level":3,"label":"Logrado","description":"Propone un control general."},{"level":2,"label":"En desarrollo","description":"Cumple el criterio de forma parcial o general, con errores u omisiones que no invalidan el resultado."},{"level":1,"label":"Inicial","description":"Lo intenta, pero con errores importantes o sin relación con el caso."},{"level":0,"label":"Sin evidencia","description":"No hay evidencia de este criterio en la entrega."}]},{"id":"comunicacion-y-fuentes","name":"Comunicación y fuentes","weight":10,"levels":[{"level":4,"label":"Destacado","description":"Entrega ordenada y profesional, con citas verificables (norma y artículo o numeral, o guía y sección) y declaración del uso de IA cuando aplica."},{"level":3,"label":"Logrado","description":"Entrega clara, con errores menores de cita."},{"level":2,"label":"En desarrollo","description":"Entrega comprensible, con citas incompletas o imprecisas."},{"level":1,"label":"Inicial","description":"Entrega difícil de seguir o sin citas."},{"level":0,"label":"Sin evidencia","description":"No hay fuentes."}]}]}$evbpmc_json$::jsonb;
  SELECT id INTO v_act FROM aula_activities
   WHERE course_id = v_curso AND title = v_t1 AND deleted_at IS NULL LIMIT 1;
