-- ════════════════════════════════════════════════════════════════
--  Curso de Buenas Prácticas de Laboratorio — BPL
--  5 quizzes · 5 actividades · 6 foros
-- ════════════════════════════════════════════════════════════════
DO $evbpl$
DECLARE
  v_curso    BIGINT;
  v_unidad   BIGINT;
  v_banco    BIGINT;
  v_pregunta BIGINT;
  v_eval     BIGINT;
  v_act      BIGINT;
  v_foro     BIGINT;
  v_t1 TEXT; v_t2 TEXT; v_t3 TEXT; v_t4 TEXT; v_t5 TEXT; v_t6 TEXT; v_t7 TEXT;
  v_j1 JSONB; v_j2 JSONB;
  v_a1 TEXT[];
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = 'Curso de Buenas Prácticas de Laboratorio — BPL' AND deleted_at IS NULL
   LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'No existe el curso Curso de Buenas Prácticas de Laboratorio — BPL: se salta.';
    RETURN;
  END IF;

  -- Si alguien cambió las unidades en el panel, no se fuerza nada.
  IF (SELECT COUNT(DISTINCT title) FROM aula_modules
       WHERE course_id = v_curso AND deleted_at IS NULL
         AND title = ANY(ARRAY['Unidad 1. Fundamentos y marco normativo de las BPL', 'Unidad 2. Sistema de gestión, acreditación y personal del laboratorio', 'Unidad 3. Instalaciones, equipos y metrología', 'Unidad 4. Reactivos, estándares, muestras e integridad de datos', 'Unidad 5. Bioseguridad, residuos peligrosos y certificación BPL INVIMA']::text[])) < 5 THEN
    RAISE NOTICE 'Buenas Prácticas de Laboratorio: sus unidades no coinciden con el paquete; se salta.';
    RETURN;
  END IF;

  UPDATE aula_courses
     SET passing_score = 70, max_attempts = 2, grade_policy = $evbpl_json${"version":1,"components":{"activities":60,"quizzes":30,"forums":10},"rounding":"half_up"}$evbpl_json$::jsonb, updated_at = NOW()
   WHERE id = v_curso;


  -- ── Quiz bpl-u1-quiz ──────────────────────────────────────
  SELECT id INTO v_unidad FROM aula_modules
   WHERE course_id = v_curso AND title = 'Unidad 1. Fundamentos y marco normativo de las BPL' AND deleted_at IS NULL
   LIMIT 1;
  IF v_unidad IS NULL THEN
    RAISE EXCEPTION 'No existe la unidad 1 (Unidad 1. Fundamentos y marco normativo de las BPL) en Buenas Prácticas de Laboratorio.';
  END IF;
  v_t1 := 'Evaluación de la Unidad 1 · Fundamentos y marco normativo de las BPL';
  v_t2 := 'Cuatro preguntas de selección múltiple con una sola respuesta correcta, ordenadas según la taxonomía de Bloom: comprender, aplicar, analizar y evaluar. Cada una vale 25 puntos. Tienes dos intentos y se conserva la nota mayor. La retroalimentación de cada opción se muestra después de enviar.';
  SELECT id INTO v_banco FROM aula_question_banks
   WHERE course_id = v_curso AND name = v_t1 AND deleted_at IS NULL LIMIT 1;
  IF v_banco IS NULL THEN
    INSERT INTO aula_question_banks (course_id, name, description)
    VALUES (v_curso, v_t1, v_t2)
    RETURNING id INTO v_banco;
  END IF;

  SELECT id INTO v_eval FROM aula_assessments
   WHERE course_id = v_curso AND title = v_t1 AND deleted_at IS NULL LIMIT 1;
  IF v_eval IS NULL THEN
    INSERT INTO aula_assessments
      (course_id, module_id, title, instructions_html, is_required, passing_score, max_attempts,
       shuffle_questions, shuffle_options, show_answers_after_submit, status, sort_order, weight)
    VALUES
      (v_curso, v_unidad, v_t1, v_t2, TRUE, 70, 2,
       FALSE, FALSE, TRUE, 'publicado', 1, 6)
    RETURNING id INTO v_eval;
  END IF;
  UPDATE aula_assessments SET status = 'publicado', updated_at = NOW() WHERE id = v_eval AND status = 'borrador';

  IF EXISTS (SELECT 1 FROM aula_attempts WHERE assessment_id = v_eval) THEN
    RAISE NOTICE 'El quiz % ya tiene intentos: no se modifican sus preguntas ni su configuración.', v_t1;
  ELSE
    UPDATE aula_assessments
       SET module_id = v_unidad, instructions_html = v_t2, is_required = TRUE,
           passing_score = 70, max_attempts = 2, shuffle_options = FALSE,
           show_answers_after_submit = TRUE, sort_order = 1, weight = 6, updated_at = NOW()
     WHERE id = v_eval;
    DELETE FROM aula_assessment_questions WHERE assessment_id = v_eval;


    v_t3 := '¿Para qué tipo de trabajo se diseñaron los principios de buenas prácticas de laboratorio de la OCDE?';
    v_t4 := 'Los principios de BPL de la OCDE se aplican a estudios no clínicos de seguridad (por ejemplo, toxicológicos) que se presentan a autoridades; se organizan con un director de estudio, un plan, una unidad de garantía de calidad y un archivo, y permiten la aceptación mutua de datos entre países.';
    v_j1 := $evbpl_json${"external_id":"bpl-u1-q1","cognitive_level":"Comprender","difficulty":"baja","lesson_title":"Principios BPL de la OCDE para estudios no clínicos","outcome":"Principios BPL de la OCDE para estudios no clínicos","source":"Principios de BPL de la OCDE."}$evbpl_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'bpl-u1-q1' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
    ELSE
      UPDATE aula_questions
         SET prompt_html = v_t3, points = 25, general_feedback = v_t4, explanation = v_t4, config = v_j1, updated_at = NOW()
       WHERE id = v_pregunta;
    END IF;
    DELETE FROM aula_question_options WHERE question_id = v_pregunta;
    INSERT INTO aula_question_options (question_id, text, is_correct, feedback, sort_order) VALUES
      (v_pregunta, 'Para el análisis rutinario de los lotes de producción en el laboratorio de control de calidad.', FALSE, 'El control de calidad rutinario tiene sus propias buenas prácticas (OMS, Resolución 3619).', 0),
      (v_pregunta, 'Para la acreditación de laboratorios de calibración ante el organismo nacional de acreditación.', FALSE, 'La acreditación de laboratorios se hace con la ISO/IEC 17025.', 1),
      (v_pregunta, 'Para estudios no clínicos de seguridad, como los toxicológicos, cuyos datos van a autoridades.', TRUE, 'Correcto. Su organización gira en torno al director del estudio y al plan de estudio.', 2),
      (v_pregunta, 'Para la fabricación de medicamentos estériles en las áreas grado A y B de las plantas.', FALSE, 'La fabricación se rige por las BPM.', 3);
    INSERT INTO aula_assessment_questions (assessment_id, question_id, sort_order, points_override)
    VALUES (v_eval, v_pregunta, 0, 25);


    v_t3 := 'Un fabricante tiene su propio laboratorio de control dentro de la planta certificada en BPM. ¿Qué marco rige ese laboratorio?';
    v_t4 := 'El control de calidad del fabricante hace parte de las BPM (Resolución 1160 de 2016). La Resolución 3619 de 2013 expidió el manual de BPL de control de calidad y exige el certificado de BPL a los laboratorios externos.';
    v_j1 := $evbpl_json${"external_id":"bpl-u1-q2","cognitive_level":"Aplicar","difficulty":"media","lesson_title":"Resolución 3619 de 2013: estructura y alcance","outcome":"Resolución 3619 de 2013: estructura y alcance","source":"Resolución 1160 de 2016; Resolución 3619 de 2013, artículo 2."}$evbpl_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'bpl-u1-q2' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
    ELSE
      UPDATE aula_questions
         SET prompt_html = v_t3, points = 25, general_feedback = v_t4, explanation = v_t4, config = v_j1, updated_at = NOW()
       WHERE id = v_pregunta;
    END IF;
    DELETE FROM aula_question_options WHERE question_id = v_pregunta;
    INSERT INTO aula_question_options (question_id, text, is_correct, feedback, sort_order) VALUES
      (v_pregunta, 'Las BPM de la Resolución 1160; el certificado de BPL de la Resolución 3619 se exige a los externos.', TRUE, 'Correcto. La Resolución 3619 exige el certificado de BPL a los laboratorios externos.', 0),
      (v_pregunta, 'Solo la ISO/IEC 17025, porque es la única norma obligatoria para cualquier laboratorio de ensayo en Colombia.', FALSE, 'La ISO/IEC 17025 es voluntaria.', 1),
      (v_pregunta, 'Los principios de la OCDE, porque todo laboratorio farmacéutico hace estudios de seguridad.', FALSE, 'Un laboratorio de control no hace estudios no clínicos de seguridad.', 2),
      (v_pregunta, 'Ninguno, porque los laboratorios internos de las plantas están exentos de requisitos sanitarios.', FALSE, 'El laboratorio interno está cubierto por las BPM del fabricante.', 3);
    INSERT INTO aula_assessment_questions (assessment_id, question_id, sort_order, points_override)
    VALUES (v_eval, v_pregunta, 1, 25);


    v_t3 := 'Un laboratorio externo tiene acreditación ISO/IEC 17025 de ONAC para métodos fisicoquímicos y quiere analizar lotes para fabricantes. ¿Qué análisis es correcto?';
