  -- ── Actividad bpl-u2-act ─────────────────────────────────
  SELECT id INTO v_unidad FROM aula_modules
   WHERE course_id = v_curso AND title = 'Unidad 2. Sistema de gestión, acreditación y personal del laboratorio' AND deleted_at IS NULL
   LIMIT 1;
