$evbpl$;


-- ════════════════════════════════════════════════════════════════
--  Curso de Buenas Prácticas de Documentación Farmacéutica
--  5 quizzes · 5 actividades · 6 foros
-- ════════════════════════════════════════════════════════════════
DO $evbpdoc$
DECLARE
  v_curso    BIGINT;
  v_unidad   BIGINT;
  v_banco    BIGINT;
  v_pregunta BIGINT;
  v_eval     BIGINT;
  v_act      BIGINT;
  v_foro     BIGINT;
  v_t1 TEXT; v_t2 TEXT; v_t3 TEXT; v_t4 TEXT; v_t5 TEXT; v_t6 TEXT; v_t7 TEXT;
  v_j1 JSONB; v_j2 JSONB;
  v_a1 TEXT[];
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = 'Curso de Buenas Prácticas de Documentación Farmacéutica' AND deleted_at IS NULL
   LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'No existe el curso Curso de Buenas Prácticas de Documentación Farmacéutica: se salta.';
    RETURN;
  END IF;

  -- Si alguien cambió las unidades en el panel, no se fuerza nada.
  IF (SELECT COUNT(DISTINCT title) FROM aula_modules
       WHERE course_id = v_curso AND deleted_at IS NULL
         AND title = ANY(ARRAY['Unidad 1. Fundamentos de las Buenas Prácticas de Documentación y marco normativo', 'Unidad 2. Jerarquía documental y redacción de procedimientos', 'Unidad 3. Control de documentos y reglas de diligenciamiento', 'Unidad 4. Registros de lote, documentación de laboratorio e integridad de datos', 'Unidad 5. Registros electrónicos, archivo y retención']::text[])) < 5 THEN
    RAISE NOTICE 'Buenas Prácticas de Documentación: sus unidades no coinciden con el paquete; se salta.';
    RETURN;
  END IF;

  UPDATE aula_courses
     SET passing_score = 70, max_attempts = 2, grade_policy = $evbpdoc_json${"version":1,"components":{"activities":60,"quizzes":30,"forums":10},"rounding":"half_up"}$evbpdoc_json$::jsonb, updated_at = NOW()
   WHERE id = v_curso;


  -- ── Quiz bpdoc-u1-quiz ──────────────────────────────────────
  SELECT id INTO v_unidad FROM aula_modules
   WHERE course_id = v_curso AND title = 'Unidad 1. Fundamentos de las Buenas Prácticas de Documentación y marco normativo' AND deleted_at IS NULL
   LIMIT 1;
  IF v_unidad IS NULL THEN
    RAISE EXCEPTION 'No existe la unidad 1 (Unidad 1. Fundamentos de las Buenas Prácticas de Documentación y marco normativo) en Buenas Prácticas de Documentación.';
  END IF;
  v_t1 := 'Evaluación de la Unidad 1 · Fundamentos de las Buenas Prácticas de Documentación y marco normativo';
  v_t2 := 'Cuatro preguntas de selección múltiple con una sola respuesta correcta, ordenadas según la taxonomía de Bloom: comprender, aplicar, analizar y evaluar. Cada una vale 25 puntos. Tienes dos intentos y se conserva la nota mayor. La retroalimentación de cada opción se muestra después de enviar.';
  SELECT id INTO v_banco FROM aula_question_banks
   WHERE course_id = v_curso AND name = v_t1 AND deleted_at IS NULL LIMIT 1;
  IF v_banco IS NULL THEN
    INSERT INTO aula_question_banks (course_id, name, description)
    VALUES (v_curso, v_t1, v_t2)
    RETURNING id INTO v_banco;
  END IF;

  SELECT id INTO v_eval FROM aula_assessments
   WHERE course_id = v_curso AND title = v_t1 AND deleted_at IS NULL LIMIT 1;
  IF v_eval IS NULL THEN
    INSERT INTO aula_assessments
      (course_id, module_id, title, instructions_html, is_required, passing_score, max_attempts,
       shuffle_questions, shuffle_options, show_answers_after_submit, status, sort_order, weight)
    VALUES
      (v_curso, v_unidad, v_t1, v_t2, TRUE, 70, 2,
       FALSE, FALSE, TRUE, 'publicado', 1, 6)
    RETURNING id INTO v_eval;
  END IF;
  UPDATE aula_assessments SET status = 'publicado', updated_at = NOW() WHERE id = v_eval AND status = 'borrador';

  IF EXISTS (SELECT 1 FROM aula_attempts WHERE assessment_id = v_eval) THEN
    RAISE NOTICE 'El quiz % ya tiene intentos: no se modifican sus preguntas ni su configuración.', v_t1;
  ELSE
    UPDATE aula_assessments
       SET module_id = v_unidad, instructions_html = v_t2, is_required = TRUE,
           passing_score = 70, max_attempts = 2, shuffle_options = FALSE,
           show_answers_after_submit = TRUE, sort_order = 1, weight = 6, updated_at = NOW()
     WHERE id = v_eval;
    DELETE FROM aula_assessment_questions WHERE assessment_id = v_eval;


    v_t3 := '¿Por qué se dice en las BPM que «lo que no está escrito no existe»?';
    v_t4 := 'La documentación es la evidencia objetiva del sistema de calidad: los procedimientos dicen cómo se hace y los registros demuestran que se hizo, quién lo hizo, cuándo y con qué resultado. Sin ella no hay trazabilidad ni base para liberar.';
    v_j1 := $evbpdoc_json${"external_id":"bpdoc-u1-q1","cognitive_level":"Comprender","difficulty":"baja","lesson_title":"\"Lo que no está escrito no existe\": propósito de la documentación","outcome":"\"Lo que no está escrito no existe\": propósito de la documentación","source":"OMS TRS 986, anexo 2, documentación; Resolución 1160 de 2016."}$evbpdoc_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'bpdoc-u1-q1' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
    ELSE
      UPDATE aula_questions
         SET prompt_html = v_t3, points = 25, general_feedback = v_t4, explanation = v_t4, config = v_j1, updated_at = NOW()
       WHERE id = v_pregunta;
    END IF;
    DELETE FROM aula_question_options WHERE question_id = v_pregunta;
    INSERT INTO aula_question_options (question_id, text, is_correct, feedback, sort_order) VALUES
      (v_pregunta, 'Porque el Invima cobra las visitas de inspección según el número de documentos que revisa en la planta.', FALSE, 'El costo de las visitas no depende de los documentos revisados.', 0),
      (v_pregunta, 'Porque los documentos reemplazan la necesidad de capacitar al personal en sus tareas de cada día.', FALSE, 'Los documentos apoyan, pero no reemplazan la formación.', 1),
      (v_pregunta, 'Porque las actividades que no se registran se consideran voluntarias para el personal de la planta.', FALSE, 'Registrar no define si algo es obligatorio: demuestra que se hizo.', 2),
      (v_pregunta, 'Porque el registro es la evidencia objetiva de que la actividad se hizo como estaba aprobada.', TRUE, 'Correcto. Sin registro no hay forma de demostrarlo ni de reconstruirlo.', 3);
    INSERT INTO aula_assessment_questions (assessment_id, question_id, sort_order, points_override)
    VALUES (v_eval, v_pregunta, 0, 25);


    v_t3 := 'Un procedimiento dice: «conservar los registros de lote al menos un año después de la fecha de vencimiento del lote». Un lote fabricado en enero de 2024 con 36 meses de vida útil vence en enero de 2027. ¿Hasta cuándo, como mínimo, se conserva su registro?';
    v_t4 := 'La retención se calcula desde la fecha que fije el procedimiento: aquí, un año después del vencimiento (enero de 2027 + 1 año = enero de 2028). La destrucción posterior se autoriza y se registra.';
    v_j1 := $evbpdoc_json${"external_id":"bpdoc-u1-q2","cognitive_level":"Aplicar","difficulty":"media","lesson_title":"Ciclo de vida de la información y riesgos de una documentación deficiente","outcome":"Ciclo de vida de la información y riesgos de una documentación deficiente","source":"OMS TRS 986, anexo 2, documentación (retención de registros de lote)."}$evbpdoc_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'bpdoc-u1-q2' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
    ELSE
      UPDATE aula_questions
         SET prompt_html = v_t3, points = 25, general_feedback = v_t4, explanation = v_t4, config = v_j1, updated_at = NOW()
       WHERE id = v_pregunta;
    END IF;
    DELETE FROM aula_question_options WHERE question_id = v_pregunta;
    INSERT INTO aula_question_options (question_id, text, is_correct, feedback, sort_order) VALUES
      (v_pregunta, 'Hasta enero de 2027, que es la misma fecha de vencimiento del lote fabricado.', FALSE, 'Falta el año adicional que fija el procedimiento.', 0),
      (v_pregunta, 'Hasta enero de 2028, un año después del vencimiento.', TRUE, 'Correcto. Vencimiento en enero de 2027 más un año.', 1),
