-- ════════════════════════════════════════════════════════════════
--  Curso de Gestión de Riesgos en la Calidad Farmacéutica
--  5 quizzes · 5 actividades · 6 foros
-- ════════════════════════════════════════════════════════════════
DO $evqrm$
DECLARE
  v_curso    BIGINT;
  v_unidad   BIGINT;
  v_banco    BIGINT;
  v_pregunta BIGINT;
  v_eval     BIGINT;
  v_act      BIGINT;
  v_foro     BIGINT;
  v_t1 TEXT; v_t2 TEXT; v_t3 TEXT; v_t4 TEXT; v_t5 TEXT; v_t6 TEXT; v_t7 TEXT;
  v_j1 JSONB; v_j2 JSONB;
  v_a1 TEXT[];
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = 'Curso de Gestión de Riesgos en la Calidad Farmacéutica' AND deleted_at IS NULL
   LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'No existe el curso Curso de Gestión de Riesgos en la Calidad Farmacéutica: se salta.';
    RETURN;
  END IF;

  -- Si alguien cambió las unidades en el panel, no se fuerza nada.
  IF (SELECT COUNT(DISTINCT title) FROM aula_modules
       WHERE course_id = v_curso AND deleted_at IS NULL
         AND title = ANY(ARRAY['Unidad 1. Fundamentos y marco normativo de la gestión de riesgos para la calidad', 'Unidad 2. El proceso de gestión de riesgos para la calidad según ICH Q9(R1)', 'Unidad 3. Herramientas de gestión de riesgos', 'Unidad 4. Aplicaciones de la gestión de riesgos en el ciclo de vida del producto', 'Unidad 5. La gestión de riesgos en la práctica regulatoria y caso integrador']::text[])) < 5 THEN
    RAISE NOTICE 'Gestión de Riesgos en la Calidad: sus unidades no coinciden con el paquete; se salta.';
    RETURN;
  END IF;

  UPDATE aula_courses
     SET passing_score = 70, max_attempts = 2, grade_policy = $evqrm_json${"version":1,"components":{"activities":60,"quizzes":30,"forums":10},"rounding":"half_up"}$evqrm_json$::jsonb, updated_at = NOW()
   WHERE id = v_curso;


  -- ── Quiz qrm-u1-quiz ──────────────────────────────────────
  SELECT id INTO v_unidad FROM aula_modules
   WHERE course_id = v_curso AND title = 'Unidad 1. Fundamentos y marco normativo de la gestión de riesgos para la calidad' AND deleted_at IS NULL
   LIMIT 1;
  IF v_unidad IS NULL THEN
    RAISE EXCEPTION 'No existe la unidad 1 (Unidad 1. Fundamentos y marco normativo de la gestión de riesgos para la calidad) en Gestión de Riesgos en la Calidad.';
  END IF;
  v_t1 := 'Evaluación de la Unidad 1 · Fundamentos y marco normativo de la gestión de riesgos para la calidad';
  v_t2 := 'Cuatro preguntas de selección múltiple con una sola respuesta correcta, ordenadas según la taxonomía de Bloom: comprender, aplicar, analizar y evaluar. Cada una vale 25 puntos. Tienes dos intentos y se conserva la nota mayor. La retroalimentación de cada opción se muestra después de enviar.';
  SELECT id INTO v_banco FROM aula_question_banks
   WHERE course_id = v_curso AND name = v_t1 AND deleted_at IS NULL LIMIT 1;
  IF v_banco IS NULL THEN
    INSERT INTO aula_question_banks (course_id, name, description)
    VALUES (v_curso, v_t1, v_t2)
    RETURNING id INTO v_banco;
  END IF;

  SELECT id INTO v_eval FROM aula_assessments
   WHERE course_id = v_curso AND title = v_t1 AND deleted_at IS NULL LIMIT 1;
  IF v_eval IS NULL THEN
    INSERT INTO aula_assessments
      (course_id, module_id, title, instructions_html, is_required, passing_score, max_attempts,
       shuffle_questions, shuffle_options, show_answers_after_submit, status, sort_order, weight)
    VALUES
      (v_curso, v_unidad, v_t1, v_t2, TRUE, 70, 2,
       FALSE, FALSE, TRUE, 'publicado', 1, 6)
    RETURNING id INTO v_eval;
  END IF;
  UPDATE aula_assessments SET status = 'publicado', updated_at = NOW() WHERE id = v_eval AND status = 'borrador';

  IF EXISTS (SELECT 1 FROM aula_attempts WHERE assessment_id = v_eval) THEN
    RAISE NOTICE 'El quiz % ya tiene intentos: no se modifican sus preguntas ni su configuración.', v_t1;
  ELSE
    UPDATE aula_assessments
       SET module_id = v_unidad, instructions_html = v_t2, is_required = TRUE,
           passing_score = 70, max_attempts = 2, shuffle_options = FALSE,
           show_answers_after_submit = TRUE, sort_order = 1, weight = 6, updated_at = NOW()
     WHERE id = v_eval;
    DELETE FROM aula_assessment_questions WHERE assessment_id = v_eval;


    v_t3 := 'Según ICH Q9(R1), ¿qué es el riesgo?';
    v_t4 := 'ICH Q9(R1) define el riesgo como la combinación de la probabilidad de que ocurra un daño y la severidad de ese daño. El peligro es la fuente potencial de daño, y la detectabilidad es la capacidad de descubrir el peligro o el daño.';
    v_j1 := $evqrm_json${"external_id":"qrm-u1-q1","cognitive_level":"Comprender","difficulty":"baja","lesson_title":"Vocabulario esencial: peligro, daño, riesgo, severidad, probabilidad y detectabilidad","outcome":"Vocabulario esencial: peligro, daño, riesgo, severidad, probabilidad y detectabilidad","source":"ICH Q9(R1), glosario."}$evqrm_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'qrm-u1-q1' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
    ELSE
      UPDATE aula_questions
         SET prompt_html = v_t3, points = 25, general_feedback = v_t4, explanation = v_t4, config = v_j1, updated_at = NOW()
       WHERE id = v_pregunta;
    END IF;
    DELETE FROM aula_question_options WHERE question_id = v_pregunta;
    INSERT INTO aula_question_options (question_id, text, is_correct, feedback, sort_order) VALUES
      (v_pregunta, 'Cualquier peligro presente en la planta, aunque nunca llegue a causar un daño a ninguna persona.', FALSE, 'Un peligro es una fuente potencial de daño; el riesgo combina probabilidad y severidad.', 0),
      (v_pregunta, 'La combinación de la probabilidad de que ocurra un daño y la severidad de ese daño.', TRUE, 'Correcto. Es la definición de ICH Q9(R1).', 1),
      (v_pregunta, 'La probabilidad de que el Invima encuentre un incumplimiento durante una visita a la planta.', FALSE, 'Ese es un riesgo regulatorio, no la definición general de riesgo.', 2),
      (v_pregunta, 'El costo económico de un retiro del mercado multiplicado por el número de lotes que se retiran.', FALSE, 'El costo puede ser una consecuencia, pero no define el riesgo para la calidad.', 3);
    INSERT INTO aula_assessment_questions (assessment_id, question_id, sort_order, points_override)
    VALUES (v_eval, v_pregunta, 0, 25);


    v_t3 := 'En una tableteadora, el desgaste de un punzón puede desprender fragmentos metálicos que terminen en las tabletas y lesionen a un paciente. ¿Cuál es el peligro?';
    v_t4 := 'Peligro es la fuente potencial de daño (el desgaste que desprende metal); daño es la lesión del paciente; la probabilidad y la severidad definen el riesgo, y la detectabilidad, la capacidad de descubrirlo a tiempo.';
    v_j1 := $evqrm_json${"external_id":"qrm-u1-q2","cognitive_level":"Aplicar","difficulty":"media","lesson_title":"Vocabulario esencial: peligro, daño, riesgo, severidad, probabilidad y detectabilidad","outcome":"Vocabulario esencial: peligro, daño, riesgo, severidad, probabilidad y detectabilidad","source":"ICH Q9(R1), glosario."}$evqrm_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'qrm-u1-q2' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
    ELSE
      UPDATE aula_questions
         SET prompt_html = v_t3, points = 25, general_feedback = v_t4, explanation = v_t4, config = v_j1, updated_at = NOW()
       WHERE id = v_pregunta;
    END IF;
    DELETE FROM aula_question_options WHERE question_id = v_pregunta;
    INSERT INTO aula_question_options (question_id, text, is_correct, feedback, sort_order) VALUES
      (v_pregunta, 'La lesión del paciente que ingiere una tableta contaminada con un fragmento metálico.', FALSE, 'Esa es el daño, la consecuencia.', 0),
      (v_pregunta, 'La baja probabilidad de que el operario note el desgaste del punzón durante su turno de trabajo.', FALSE, 'Eso se relaciona con la detectabilidad.', 1),
      (v_pregunta, 'El costo de reemplazar el punzón antes de que termine su vida útil prevista por el fabricante.', FALSE, 'El costo no es el peligro para el paciente.', 2),
      (v_pregunta, 'El desgaste del punzón que puede desprender fragmentos metálicos.', TRUE, 'Correcto. Es la fuente potencial del daño.', 3);
    INSERT INTO aula_assessment_questions (assessment_id, question_id, sort_order, points_override)
    VALUES (v_eval, v_pregunta, 1, 25);


    v_t3 := '¿Qué diferencia principal hay entre ICH Q9(R1) e ISO 31000?';
    v_t4 := 'ICH Q9(R1) aplica la gestión de riesgos a la calidad de los medicamentos, con el paciente como referencia; ISO 31000 da principios y un marco genérico para cualquier riesgo organizacional. La OMS (TRS 981, anexo 2) ofrece una guía afín a ICH Q9.';
    v_j1 := $evqrm_json${"external_id":"qrm-u1-q3","cognitive_level":"Analizar","difficulty":"media","lesson_title":"Marco internacional: ICH Q9(R1), OMS TRS 981 Anexo 2 e ISO 31000","outcome":"Marco internacional: ICH Q9(R1), OMS TRS 981 Anexo 2 e ISO 31000","source":"ICH Q9(R1); ISO 31000:2018; OMS TRS 981, anexo 2."}$evqrm_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'qrm-u1-q3' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
    ELSE
      UPDATE aula_questions
         SET prompt_html = v_t3, points = 25, general_feedback = v_t4, explanation = v_t4, config = v_j1, updated_at = NOW()
       WHERE id = v_pregunta;
    END IF;
