-- ════════════════════════════════════════════════════════════════
--  Curso de Gestión de Desviaciones y Acciones Correctivas y Preventivas — CAPA
--  5 quizzes · 5 actividades · 6 foros
-- ════════════════════════════════════════════════════════════════
DO $evcapa$
DECLARE
  v_curso    BIGINT;
  v_unidad   BIGINT;
  v_banco    BIGINT;
  v_pregunta BIGINT;
  v_eval     BIGINT;
  v_act      BIGINT;
  v_foro     BIGINT;
  v_t1 TEXT; v_t2 TEXT; v_t3 TEXT; v_t4 TEXT; v_t5 TEXT; v_t6 TEXT; v_t7 TEXT;
  v_j1 JSONB; v_j2 JSONB;
  v_a1 TEXT[];
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = 'Curso de Gestión de Desviaciones y Acciones Correctivas y Preventivas — CAPA' AND deleted_at IS NULL
   LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'No existe el curso Curso de Gestión de Desviaciones y Acciones Correctivas y Preventivas — CAPA: se salta.';
    RETURN;
  END IF;

  -- Si alguien cambió las unidades en el panel, no se fuerza nada.
  IF (SELECT COUNT(DISTINCT title) FROM aula_modules
       WHERE course_id = v_curso AND deleted_at IS NULL
         AND title = ANY(ARRAY['Unidad 1. Fundamentos de las desviaciones y marco regulatorio', 'Unidad 2. Detección, registro, contención y evaluación de impacto', 'Unidad 3. Investigación de causa raíz y error humano', 'Unidad 4. Investigación de resultados fuera de especificación (OOS) y quejas', 'Unidad 5. Sistema CAPA, efectividad, indicadores e inspecciones']::text[])) < 5 THEN
    RAISE NOTICE 'Desviaciones y CAPA: sus unidades no coinciden con el paquete; se salta.';
    RETURN;
  END IF;

  UPDATE aula_courses
     SET passing_score = 70, max_attempts = 2, grade_policy = $evcapa_json${"version":1,"components":{"activities":60,"quizzes":30,"forums":10},"rounding":"half_up"}$evcapa_json$::jsonb, updated_at = NOW()
   WHERE id = v_curso;


  -- ── Quiz capa-u1-quiz ──────────────────────────────────────
  SELECT id INTO v_unidad FROM aula_modules
   WHERE course_id = v_curso AND title = 'Unidad 1. Fundamentos de las desviaciones y marco regulatorio' AND deleted_at IS NULL
   LIMIT 1;
  IF v_unidad IS NULL THEN
    RAISE EXCEPTION 'No existe la unidad 1 (Unidad 1. Fundamentos de las desviaciones y marco regulatorio) en Desviaciones y CAPA.';
  END IF;
  v_t1 := 'Evaluación de la Unidad 1 · Fundamentos de las desviaciones y marco regulatorio';
  v_t2 := 'Cuatro preguntas de selección múltiple con una sola respuesta correcta, ordenadas según la taxonomía de Bloom: comprender, aplicar, analizar y evaluar. Cada una vale 25 puntos. Tienes dos intentos y se conserva la nota mayor. La retroalimentación de cada opción se muestra después de enviar.';
  SELECT id INTO v_banco FROM aula_question_banks
   WHERE course_id = v_curso AND name = v_t1 AND deleted_at IS NULL LIMIT 1;
  IF v_banco IS NULL THEN
    INSERT INTO aula_question_banks (course_id, name, description)
    VALUES (v_curso, v_t1, v_t2)
    RETURNING id INTO v_banco;
  END IF;

  SELECT id INTO v_eval FROM aula_assessments
   WHERE course_id = v_curso AND title = v_t1 AND deleted_at IS NULL LIMIT 1;
  IF v_eval IS NULL THEN
    INSERT INTO aula_assessments
      (course_id, module_id, title, instructions_html, is_required, passing_score, max_attempts,
       shuffle_questions, shuffle_options, show_answers_after_submit, status, sort_order, weight)
    VALUES
      (v_curso, v_unidad, v_t1, v_t2, TRUE, 70, 2,
       FALSE, FALSE, TRUE, 'publicado', 1, 6)
    RETURNING id INTO v_eval;
  END IF;
  UPDATE aula_assessments SET status = 'publicado', updated_at = NOW() WHERE id = v_eval AND status = 'borrador';

  IF EXISTS (SELECT 1 FROM aula_attempts WHERE assessment_id = v_eval) THEN
    RAISE NOTICE 'El quiz % ya tiene intentos: no se modifican sus preguntas ni su configuración.', v_t1;
  ELSE
    UPDATE aula_assessments
       SET module_id = v_unidad, instructions_html = v_t2, is_required = TRUE,
           passing_score = 70, max_attempts = 2, shuffle_options = FALSE,
           show_answers_after_submit = TRUE, sort_order = 1, weight = 6, updated_at = NOW()
     WHERE id = v_eval;
    DELETE FROM aula_assessment_questions WHERE assessment_id = v_eval;


    v_t3 := '¿Qué es una desviación en el contexto de las BPM?';
    v_t4 := 'Una desviación es un apartamiento de una instrucción aprobada o de un estándar establecido (procedimiento, registro de lote, especificación de proceso). Se distingue de un resultado OOS, de una queja y de un cambio, aunque pueden relacionarse.';
    v_j1 := $evcapa_json${"external_id":"capa-u1-q1","cognitive_level":"Comprender","difficulty":"baja","lesson_title":"Desviación, no conformidad, OOS y queja: definiciones y diferencias","outcome":"Desviación, no conformidad, OOS y queja: definiciones y diferencias","source":"Resolución 1160 de 2016; ICH Q10; OMS TRS 986, anexo 2."}$evcapa_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'capa-u1-q1' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
    ELSE
      UPDATE aula_questions
         SET prompt_html = v_t3, points = 25, general_feedback = v_t4, explanation = v_t4, config = v_j1, updated_at = NOW()
       WHERE id = v_pregunta;
    END IF;
    DELETE FROM aula_question_options WHERE question_id = v_pregunta;
    INSERT INTO aula_question_options (question_id, text, is_correct, feedback, sort_order) VALUES
      (v_pregunta, 'Cualquier queja que presenta un cliente sobre el precio o la entrega del producto que compró.', FALSE, 'Una queja comercial no es una desviación de BPM.', 0),
      (v_pregunta, 'Un resultado de laboratorio que cumple la especificación, pero es distinto del resultado anterior.', FALSE, 'Eso puede ser un resultado fuera de tendencia, no necesariamente una desviación.', 1),
      (v_pregunta, 'Un cambio planificado y aprobado en el control de cambios antes de su implementación.', FALSE, 'Un cambio aprobado no es una desviación.', 2),
      (v_pregunta, 'Un apartamiento de una instrucción aprobada, un procedimiento o un estándar establecido.', TRUE, 'Correcto. Puede ser planeada o no planeada.', 3);
    INSERT INTO aula_assessment_questions (assessment_id, question_id, sort_order, points_override)
    VALUES (v_eval, v_pregunta, 0, 25);


    v_t3 := 'Por un daño en la tableteadora habitual, producción quiere fabricar un lote en otra tableteadora del mismo modelo, calificada, que no figura en el registro de lote. ¿Cómo se gestiona?';
    v_t4 := 'Una desviación planeada es un apartamiento temporal y conocido de antemano que se evalúa (riesgo, impacto) y se aprueba antes de ejecutarse. Si el cambio va a ser permanente, se gestiona por control de cambios.';
    v_j1 := $evcapa_json${"external_id":"capa-u1-q2","cognitive_level":"Aplicar","difficulty":"media","lesson_title":"Desviaciones planeadas y no planeadas","outcome":"Desviaciones planeadas y no planeadas","source":"Resolución 1160 de 2016; ICH Q10, gestión del cambio."}$evcapa_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'capa-u1-q2' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
    ELSE
      UPDATE aula_questions
         SET prompt_html = v_t3, points = 25, general_feedback = v_t4, explanation = v_t4, config = v_j1, updated_at = NOW()
       WHERE id = v_pregunta;
    END IF;
    DELETE FROM aula_question_options WHERE question_id = v_pregunta;
    INSERT INTO aula_question_options (question_id, text, is_correct, feedback, sort_order) VALUES
      (v_pregunta, 'Se fabrica sin ningún registro adicional, porque ambos equipos son del mismo modelo y fabricante.', FALSE, 'Usar un equipo distinto del indicado es un apartamiento que debe evaluarse.', 0),
      (v_pregunta, 'Como desviación planeada: se evalúa y se aprueba antes de ejecutarla, con su impacto documentado.', TRUE, 'Correcto. Si el uso fuera permanente, se tramitaría por control de cambios.', 1),
      (v_pregunta, 'Se gestiona como una queja de calidad dirigida al proveedor de la tableteadora que se dañó.', FALSE, 'El daño del equipo no convierte esto en una queja.', 2),
      (v_pregunta, 'Se fabrica y al final se abre una desviación no planeada, solo si algo llega a salir mal.', FALSE, 'Si se sabe de antemano, se evalúa y aprueba antes.', 3);
    INSERT INTO aula_assessment_questions (assessment_id, question_id, sort_order, points_override)
    VALUES (v_eval, v_pregunta, 1, 25);


    v_t3 := '¿Cuál de estas desviaciones tiene mayor criticidad?';
    v_t4 := 'La criticidad se basa en el riesgo para la calidad y el paciente. Un filtro esterilizante que falla la integridad compromete la esterilidad de un inyectable: es una desviación crítica.';
    v_j1 := $evcapa_json${"external_id":"capa-u1-q3","cognitive_level":"Analizar","difficulty":"media","lesson_title":"Clasificación por criticidad: crítica, mayor y menor","outcome":"Clasificación por criticidad: crítica, mayor y menor","source":"ICH Q9(R1); Anexo 1 de las BPM de la UE (integridad de filtros)."}$evcapa_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'capa-u1-q3' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
    ELSE
      UPDATE aula_questions
         SET prompt_html = v_t3, points = 25, general_feedback = v_t4, explanation = v_t4, config = v_j1, updated_at = NOW()
       WHERE id = v_pregunta;
    END IF;
