-- ════════════════════════════════════════════════════════════════
--  Curso de Validación de Métodos Analíticos
--  5 quizzes · 5 actividades · 6 foros
-- ════════════════════════════════════════════════════════════════
DO $evvma$
DECLARE
  v_curso    BIGINT;
  v_unidad   BIGINT;
  v_banco    BIGINT;
  v_pregunta BIGINT;
  v_eval     BIGINT;
  v_act      BIGINT;
  v_foro     BIGINT;
  v_t1 TEXT; v_t2 TEXT; v_t3 TEXT; v_t4 TEXT; v_t5 TEXT; v_t6 TEXT; v_t7 TEXT;
  v_j1 JSONB; v_j2 JSONB;
  v_a1 TEXT[];
BEGIN
  SELECT id INTO v_curso FROM aula_courses
   WHERE kind = 'edvanta' AND title = 'Curso de Validación de Métodos Analíticos' AND deleted_at IS NULL
   LIMIT 1;
  IF v_curso IS NULL THEN
    RAISE NOTICE 'No existe el curso Curso de Validación de Métodos Analíticos: se salta.';
    RETURN;
  END IF;

  -- Si alguien cambió las unidades en el panel, no se fuerza nada.
  IF (SELECT COUNT(DISTINCT title) FROM aula_modules
       WHERE course_id = v_curso AND deleted_at IS NULL
         AND title = ANY(ARRAY['Unidad 1. Fundamentos y marco regulatorio de la validación analítica', 'Unidad 2. Parámetros de desempeño del método', 'Unidad 3. Diseño experimental y estadística aplicada', 'Unidad 4. Métodos indicadores de estabilidad y métodos microbiológicos', 'Unidad 5. Documentación, ciclo de vida y casos prácticos']::text[])) < 5 THEN
    RAISE NOTICE 'Validación de Métodos Analíticos: sus unidades no coinciden con el paquete; se salta.';
    RETURN;
  END IF;

  UPDATE aula_courses
     SET passing_score = 70, max_attempts = 2, grade_policy = $evvma_json${"version":1,"components":{"activities":60,"quizzes":30,"forums":10},"rounding":"half_up"}$evvma_json$::jsonb, updated_at = NOW()
   WHERE id = v_curso;


  -- ── Quiz vma-u1-quiz ──────────────────────────────────────
  SELECT id INTO v_unidad FROM aula_modules
   WHERE course_id = v_curso AND title = 'Unidad 1. Fundamentos y marco regulatorio de la validación analítica' AND deleted_at IS NULL
   LIMIT 1;
  IF v_unidad IS NULL THEN
    RAISE EXCEPTION 'No existe la unidad 1 (Unidad 1. Fundamentos y marco regulatorio de la validación analítica) en Validación de Métodos Analíticos.';
  END IF;
  v_t1 := 'Evaluación de la Unidad 1 · Fundamentos y marco regulatorio de la validación analítica';
  v_t2 := 'Cuatro preguntas de selección múltiple con una sola respuesta correcta, ordenadas según la taxonomía de Bloom: comprender, aplicar, analizar y evaluar. Cada una vale 25 puntos. Tienes dos intentos y se conserva la nota mayor. La retroalimentación de cada opción se muestra después de enviar.';
  SELECT id INTO v_banco FROM aula_question_banks
   WHERE course_id = v_curso AND name = v_t1 AND deleted_at IS NULL LIMIT 1;
  IF v_banco IS NULL THEN
    INSERT INTO aula_question_banks (course_id, name, description)
    VALUES (v_curso, v_t1, v_t2)
    RETURNING id INTO v_banco;
  END IF;

  SELECT id INTO v_eval FROM aula_assessments
   WHERE course_id = v_curso AND title = v_t1 AND deleted_at IS NULL LIMIT 1;
  IF v_eval IS NULL THEN
    INSERT INTO aula_assessments
      (course_id, module_id, title, instructions_html, is_required, passing_score, max_attempts,
       shuffle_questions, shuffle_options, show_answers_after_submit, status, sort_order, weight)
    VALUES
      (v_curso, v_unidad, v_t1, v_t2, TRUE, 70, 2,
       FALSE, FALSE, TRUE, 'publicado', 1, 6)
    RETURNING id INTO v_eval;
  END IF;
  UPDATE aula_assessments SET status = 'publicado', updated_at = NOW() WHERE id = v_eval AND status = 'borrador';

  IF EXISTS (SELECT 1 FROM aula_attempts WHERE assessment_id = v_eval) THEN
    RAISE NOTICE 'El quiz % ya tiene intentos: no se modifican sus preguntas ni su configuración.', v_t1;
  ELSE
    UPDATE aula_assessments
       SET module_id = v_unidad, instructions_html = v_t2, is_required = TRUE,
           passing_score = 70, max_attempts = 2, shuffle_options = FALSE,
           show_answers_after_submit = TRUE, sort_order = 1, weight = 6, updated_at = NOW()
     WHERE id = v_eval;
    DELETE FROM aula_assessment_questions WHERE assessment_id = v_eval;


    v_t3 := '¿Qué es el perfil objetivo analítico (ATP) de ICH Q14?';
    v_t4 := 'El perfil objetivo analítico describe qué debe medir el procedimiento y con qué desempeño (por ejemplo, exactitud y precisión en un rango), y guía el desarrollo y la validación con el enfoque de ciclo de vida de ICH Q14 y Q2(R2).';
    v_j1 := $evvma_json${"external_id":"vma-u1-q1","cognitive_level":"Comprender","difficulty":"baja","lesson_title":"ICH Q2(R2) e ICH Q14: el nuevo enfoque de ciclo de vida","outcome":"ICH Q2(R2) e ICH Q14: el nuevo enfoque de ciclo de vida","source":"ICH Q14, perfil objetivo analítico; ICH Q2(R2)."}$evvma_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'vma-u1-q1' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
    ELSE
      UPDATE aula_questions
         SET prompt_html = v_t3, points = 25, general_feedback = v_t4, explanation = v_t4, config = v_j1, updated_at = NOW()
       WHERE id = v_pregunta;
    END IF;
    DELETE FROM aula_question_options WHERE question_id = v_pregunta;
    INSERT INTO aula_question_options (question_id, text, is_correct, feedback, sort_order) VALUES
      (v_pregunta, 'La descripción del propósito del método y del desempeño que debe alcanzar.', TRUE, 'Correcto. Orienta el desarrollo, la validación y el ciclo de vida del método.', 0),
      (v_pregunta, 'La lista de equipos y de reactivos que el laboratorio compró para ejecutar el método analítico.', FALSE, 'Es un inventario de recursos, no el perfil objetivo.', 1),
      (v_pregunta, 'El informe final de validación firmado por el jefe de control de calidad del laboratorio.', FALSE, 'El informe documenta la validación; el ATP la precede.', 2),
      (v_pregunta, 'El certificado de calibración del equipo cromatográfico que se usará para ejecutar el método.', FALSE, 'La calibración es un requisito del equipo, no el perfil del método.', 3);
    INSERT INTO aula_assessment_questions (assessment_id, question_id, sort_order, points_override)
    VALUES (v_eval, v_pregunta, 0, 25);


    v_t3 := 'Un laboratorio va a usar el método de valoración de la monografía vigente de la USP para su producto. ¿Qué debe hacer?';
    v_t4 := 'Un método compendial no se valida de nuevo, pero se verifica su idoneidad en las condiciones de uso (producto, equipos, personal), según el capítulo 1226 de la USP; la validación completa aplica a métodos propios o modificados.';
    v_j1 := $evvma_json${"external_id":"vma-u1-q2","cognitive_level":"Aplicar","difficulty":"media","lesson_title":"Validación, verificación, transferencia y calificación","outcome":"Validación, verificación, transferencia y calificación","source":"USP, capítulos 1225 y 1226."}$evvma_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'vma-u1-q2' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
    ELSE
      UPDATE aula_questions
         SET prompt_html = v_t3, points = 25, general_feedback = v_t4, explanation = v_t4, config = v_j1, updated_at = NOW()
       WHERE id = v_pregunta;
    END IF;
    DELETE FROM aula_question_options WHERE question_id = v_pregunta;
    INSERT INTO aula_question_options (question_id, text, is_correct, feedback, sort_order) VALUES
      (v_pregunta, 'Validarlo por completo con todos los parámetros de ICH Q2(R2), como si fuera un método propio.', FALSE, 'La validación completa no se exige para un método compendial.', 0),
      (v_pregunta, 'Nada, porque un método de la farmacopea ya está validado para cualquier producto y laboratorio.', FALSE, 'Falta demostrar su idoneidad en las condiciones reales de uso.', 1),
      (v_pregunta, 'Verificar que el método funciona con su producto y en sus condiciones.', TRUE, 'Correcto. Es la verificación del capítulo 1226 de la USP.', 2),
      (v_pregunta, 'Transferirlo desde la USP con un protocolo entre un laboratorio emisor y uno receptor.', FALSE, 'La transferencia ocurre entre laboratorios, no desde la farmacopea.', 3);
    INSERT INTO aula_assessment_questions (assessment_id, question_id, sort_order, points_override)
    VALUES (v_eval, v_pregunta, 1, 25);


    v_t3 := '¿Qué parámetros necesita un método para cuantificar una impureza (prueba cuantitativa de impurezas)?';
    v_t4 := 'Los parámetros dependen del tipo de procedimiento: una prueba cuantitativa de impurezas exige especificidad, exactitud, precisión, respuesta lineal en el rango y límite de cuantificación; una prueba límite exige especificidad y límite de detección; la identificación, especificidad.';
    v_j1 := $evvma_json${"external_id":"vma-u1-q3","cognitive_level":"Analizar","difficulty":"media","lesson_title":"Categorías de métodos y parámetros requeridos","outcome":"Categorías de métodos y parámetros requeridos","source":"ICH Q2(R2), tabla de características por tipo de procedimiento; USP, capítulo 1225."}$evvma_json$::jsonb;
    SELECT id INTO v_pregunta FROM aula_questions
     WHERE bank_id = v_banco AND config->>'external_id' = 'vma-u1-q3' AND deleted_at IS NULL LIMIT 1;
    IF v_pregunta IS NULL THEN
      INSERT INTO aula_questions (bank_id, type, prompt_html, points, general_feedback, explanation, config)
      VALUES (v_banco, 'unica', v_t3, 25, v_t4, v_t4, v_j1)
      RETURNING id INTO v_pregunta;
    ELSE
      UPDATE aula_questions
         SET prompt_html = v_t3, points = 25, general_feedback = v_t4, explanation = v_t4, config = v_j1, updated_at = NOW()
       WHERE id = v_pregunta;
