  -- ── Actividad vma-proyecto-1 ─────────────────────────────────
  SELECT id INTO v_unidad FROM aula_modules
   WHERE course_id = v_curso AND title = 'Unidad 3. Diseño experimental y estadística aplicada' AND deleted_at IS NULL
